/** What a file system's Curate pane draws, as text (a database's moved onto the Curate tabs in Brief S2, so its half of
 *  the fixture is gone), for the byte-for-byte pin in curate-tabs-repo.test.mjs. The fixture (curate-nonrepo.fixture.json) was generated by running THIS function
 *  against main's tree (before the repository tabs), so the test fails if the tabs change what these two draw.
 *  Regenerated deliberately by Brief F (2026-10-11): its only differences are the band words it means to change
 *  (one rating per person, "sent with Publish", journal entries are public Notes).
 *  Regenerated again by Files step 1 (2026-10-20): the only difference is the Publish band, which now carries a file
 *  system's one Publish and its root-folder state instead of the sentence "no publish control here yet".
 *  The stub server is fixed and time-free so the output does not drift. */
import { makeDomEnvironment, ensureLoaderRegistered } from './dom-harness.mjs';

const wait = (ms = 250) => new Promise((r) => setTimeout(r, ms));

export async function snapshotNonRepoCurate(kind) {
  const { document, window } = makeDomEnvironment();
  globalThis.fetch = async (url) => {
    const u = String(url);
    const ok = (body) => ({ ok: true, status: 200, json: async () => body });
    if (u.includes('/questions')) return ok({ questions: [] });
    if (u.includes('/api/context/')) return ok({ enrichment: {}, question_answers: {} });
    if (u.includes('/investigations') || u.includes('/subscriptions') || u.includes('/schedules')) return ok([]);
    if (u.includes('/api/curate/')) return ok([]);
    return ok({});
  };
  ensureLoaderRegistered();
  globalThis.location = window.location; globalThis.history = window.history;
  window.matchMedia = window.matchMedia || (() => ({ matches: true, addEventListener() {}, removeEventListener() {} }));
  const app = await import('/static/next/app.js');
  Object.assign(app.state, { resourceType: kind, selectedSlug: 'fixture_resource', stage: 'scouting', subTab: 'questions',
    investigations: [], investigation: '', workListSlug: null, workListIndex: false, me: { user_id: 'dan' }, curate: {},
    curateSelection: null, groups: [], perspectives: [], allPerspectives: [],
    projects: [], databases: [{ slug: 'fixture_resource', display_name: 'Fixture' }], filesystems: [{ slug: 'fixture_resource', display_name: 'Fixture' }],
    databasesLoaded: true, filesystemsLoaded: true });
  for (const id of ['content', 'intent-nav', 'rail-evidence', 'perspective-row', 'app-grid']) {
    const d = document.createElement('div'); d.id = id; document.body.appendChild(d);
  }
  app.renderIntentNav();
  document.querySelector('#intent-nav button[data-stage="curate"]').click();
  await wait(500);
  const rail = app.subTabsHtml();
  const content = document.getElementById('content').innerHTML;
  return { rail, content };
}
